/**
 * Carga de prueba fija para poder ejecutar el workflow sin depender del
 * formulario. Es la ruta de respaldo documentada en el plan operativo.
 */
return [{
  json: {
    'Customer name': 'Demo Customer',
    'Email': 'customer@example.com',
    'Phone': '+34600000000',
    'Message': 'Hi, do you have a 6-seat van available from 12-19 August for 2 adults and 2 kids?'
  }
}];

/**
 * NODO: Normalize Inbound Request
 * MODO: Run Once for All Items (modo por defecto de n8n)
 *
 * Convierte cualquier entrada (webhook del Google Form o Manual Trigger) en el
 * contrato canonico que consume el resto del workflow, e inyecta la
 * trazabilidad: trace_id, client_id y organization_id.
 *
 * Es el unico punto donde se normaliza. Anadir un canal nuevo (WhatsApp, email)
 * solo requiere que envie al webhook; nada aguas abajo cambia.
 */

// $input.first() en lugar de $json: $json no esta disponible en el modo
// "Run Once for All Items", que es el modo por defecto del nodo Code.
const entrada = $input.first().json;

// El webhook envuelve el cuerpo en .body; el Manual Trigger no.
const datos = entrada.body || entrada;

/** Devuelve el primer valor no vacio de los que se le pasen. */
function primero(...valores) {
  for (const v of valores) {
    if (v !== undefined && v !== null && String(v).trim() !== '') {
      return String(v).trim();
    }
  }
  return '';
}

return [{
  json: {
    // --- Contexto de tenant y trazabilidad -------------------------------
    client_id: 'demo_tourism_operator',
    organization_id: 'worklings_demo',
    trace_id: String($execution.id),
    source_channel: primero(datos.source_channel, 'manual_test'),
    received_at: new Date().toISOString(),

    // --- Datos del cliente: se aceptan varias grafias de clave -----------
    customer_name: primero(datos['Customer name'], datos.customer_name, datos.name),
    customer_email: primero(datos['Email'], datos.customer_email, datos.email),
    customer_phone: primero(datos['Phone'], datos.customer_phone, datos.phone),
    raw_message: primero(datos['Message'], datos.message, datos.raw_message, datos.text),

    // --- Modo de operacion: constante, no negociable ---------------------
    response_mode: 'human_approval_required',
    customer_message_sent: false
  }
}];

/**
 * NODO: Validate Agent Output
 * MODO: Run Once for All Items (modo por defecto de n8n)
 *
 * POR QUE EXISTE ESTE NODO
 * La respuesta de un LLM no es un contrato fiable: puede llegar envuelta en
 * markdown, con campos ausentes, con un array convertido en string, o sin ser
 * JSON en absoluto. Los nodos posteriores (Sheets, Calendar, Slack) leen rutas
 * anidadas como $json.service_type.label y reventarian en cualquiera de esos
 * casos, tumbando la demo en directo.
 *
 * Este nodo es la frontera de fiabilidad del workflow y garantiza tres cosas:
 *
 *   1. FORMA         La salida tiene SIEMPRE la misma estructura completa,
 *                    aunque el modelo devuelva basura. Nada aguas abajo rompe.
 *   2. TRAZABILIDAD  trace_id, client_id y organization_id se recuperan del
 *                    nodo Normalize y no de la respuesta del modelo, asi que no
 *                    se pierden aunque el LLM los omita.
 *   3. SEGURIDAD     Las banderas de confirmacion y de envio se fuerzan a false
 *                    aqui, en codigo. No dependen de que el modelo se porte bien.
 *
 * Resultado: si el LLM falla, el lead entra igualmente en Sheets y el equipo
 * recibe igualmente el aviso en Slack, marcado como needs_human_review.
 * El sistema degrada, no se cae.
 */

// Nombre exacto del nodo de normalizacion. Cambiar aqui si se renombra.
const NODO_NORMALIZE = 'Normalize Inbound Request';

// ---------------------------------------------------------------------------
// Contexto de origen
// ---------------------------------------------------------------------------
let origen = {};
try {
  origen = $(NODO_NORMALIZE).first().json || {};
} catch (error) {
  origen = {};
}

// ---------------------------------------------------------------------------
// Utilidades de saneado
// ---------------------------------------------------------------------------

/** Localiza el texto de la respuesta del LLM, venga en el campo que venga. */
function extraerRespuestaLLM(item) {
  if (!item) return null;
  return (
    item.choices?.[0]?.message?.content ??
    item.message?.content ??
    item.text ??
    item.output ??
    item.content ??
    null
  );
}

/** Parsea JSON tolerando vallas de markdown y texto alrededor. */
function parsearJSON(valor) {
  if (valor === null || valor === undefined) return null;
  if (typeof valor === 'object') return valor;

  const limpio = String(valor)
    .replace(/^\s*```(?:json)?/i, '')
    .replace(/```\s*$/, '')
    .trim();

  try {
    return JSON.parse(limpio);
  } catch (error) {
    // Segundo intento: quedarse con el primer bloque {...} que aparezca.
    const inicio = limpio.indexOf('{');
    const fin = limpio.lastIndexOf('}');
    if (inicio === -1 || fin === -1 || fin <= inicio) return null;
    try {
      return JSON.parse(limpio.slice(inicio, fin + 1));
    } catch (errorSegundoIntento) {
      return null;
    }
  }
}

const esObjeto = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const aObjeto = (v) => (esObjeto(v) ? v : {});

const aTexto = (v, porDefecto = '') =>
  typeof v === 'string' && v.trim() !== '' ? v.trim() : porDefecto;

const aNumero = (v, porDefecto = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : porDefecto;
};

const aEnteroONulo = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isInteger(n) ? n : null;
};

/** Convierte a array de strings. Acepta array, string suelto o coma-separado. */
const aLista = (v) => {
  if (Array.isArray(v)) return v.map((x) => String(x).trim()).filter(Boolean);
  if (typeof v === 'string' && v.trim() !== '') {
    return v.split(',').map((x) => x.trim()).filter(Boolean);
  }
  return [];
};

/** Fuerza el valor a uno de los permitidos. */
const aEnumerado = (v, permitidos, porDefecto) => {
  const t = aTexto(v).toLowerCase();
  return permitidos.includes(t) ? t : porDefecto;
};

// ---------------------------------------------------------------------------
// Construccion del objeto de salida con forma garantizada
// ---------------------------------------------------------------------------

// Campos que el LLM deberia haber devuelto. Los que falten se registran en
// validation_missing_fields: es la senal de evaluacion del reliability brief.
const CAMPOS_ESPERADOS = [
  'language',
  'service_type',
  'dates',
  'group_size',
  'customer_intent',
  'booking_intent',
  'urgency',
  'missing_information',
  'recommended_next_action',
  'lead_status',
  'handoff_reason',
  'human_handoff_summary',
  'calendar_action',
  'safe_customer_reply_draft'
];

const BORRADOR_SEGURO_POR_DEFECTO =
  'Hi, thanks for your message. Our team is reviewing your request and will ' +
  'get back to you shortly with the available options.';

function construirLead(datosLLM, parseoCorrecto) {
  const d = aObjeto(datosLLM);

  const camposAusentes = parseoCorrecto
    ? CAMPOS_ESPERADOS.filter((c) => d[c] === undefined || d[c] === null)
    : ['valid_json'];

  const cliente = aObjeto(d.customer);
  const servicio = aObjeto(d.service_type);
  const fechas = aObjeto(d.dates);
  const grupo = aObjeto(d.group_size);
  const intencion = aObjeto(d.customer_intent);
  const reserva = aObjeto(d.booking_intent);
  const urgencia = aObjeto(d.urgency);
  const calendario = aObjeto(d.calendar_action);

  const traceId = aTexto(origen.trace_id, aTexto(d.trace_id, String($execution.id)));

  return {
    // --- Trazabilidad: siempre desde el origen, nunca solo desde el LLM ----
    client_id: aTexto(origen.client_id, aTexto(d.client_id, 'demo_tourism_operator')),
    organization_id: aTexto(origen.organization_id, aTexto(d.organization_id, 'worklings_demo')),
    trace_id: traceId,
    source_channel: aTexto(origen.source_channel, aTexto(d.source_channel, 'unknown')),
    received_at: aTexto(origen.received_at, aTexto(d.received_at, new Date().toISOString())),
    response_mode: 'human_approval_required',

    // --- Datos del cliente: el origen manda sobre lo que diga el LLM -------
    customer: {
      name: aTexto(origen.customer_name, aTexto(cliente.name)),
      email: aTexto(origen.customer_email, aTexto(cliente.email)),
      phone: aTexto(origen.customer_phone, aTexto(cliente.phone))
    },
    original_message: aTexto(origen.raw_message, aTexto(d.original_message)),

    // --- Extraccion del agente --------------------------------------------
    language: aTexto(d.language, 'unknown'),

    service_type: {
      label: aTexto(servicio.label, 'unknown'),
      confidence: aNumero(servicio.confidence, 0),
      evidence: aTexto(servicio.evidence)
    },

    dates: {
      start: aTexto(fechas.start),
      end: aTexto(fechas.end),
      raw: aTexto(fechas.raw),
      confidence: aNumero(fechas.confidence, 0),
      needs_year_confirmation: Boolean(fechas.needs_year_confirmation)
    },

    group_size: {
      total: aEnteroONulo(grupo.total),
      adults: aEnteroONulo(grupo.adults),
      children: aEnteroONulo(grupo.children),
      raw: aTexto(grupo.raw),
      confidence: aNumero(grupo.confidence, 0)
    },

    customer_intent: {
      label: aTexto(intencion.label, parseoCorrecto ? 'unknown' : 'manual_review_required'),
      summary: aTexto(intencion.summary, parseoCorrecto ? '' : 'AI extraction failed.'),
      confidence: aNumero(intencion.confidence, 0)
    },

    booking_intent: {
      label: aEnumerado(reserva.label, ['low', 'medium', 'high'], 'medium'),
      score: aNumero(reserva.score, 0.5),
      reason: aTexto(reserva.reason, parseoCorrecto ? '' : 'Manual review required.')
    },

    urgency: {
      label: aEnumerado(urgencia.label, ['low', 'medium', 'high'], 'medium'),
      reason: aTexto(urgencia.reason)
    },

    missing_information: parseoCorrecto
      ? aLista(d.missing_information)
      : ['manual_review_required'],

    recommended_next_action: aTexto(
      d.recommended_next_action,
      'Manual review required: a human should read the original message.'
    ),

    lead_status: parseoCorrecto
      ? aEnumerado(
          d.lead_status,
          ['new_lead', 'needs_human_review', 'needs_clarification', 'low_intent'],
          'needs_human_review'
        )
      : 'needs_human_review',

    // --- Handoff humano: siempre requerido en esta version -----------------
    handoff_required: true,
    handoff_reason: parseoCorrecto
      ? aTexto(d.handoff_reason, 'Human approval required before any customer contact.')
      : 'LLM output was not valid JSON.',
    human_handoff_summary: aTexto(
      d.human_handoff_summary,
      'Manual review required. The Workling could not parse the request safely.'
    ),

    calendar_action: {
      create_internal_event: true,
      title: aTexto(calendario.title, 'Review booking request - ' + traceId),
      description: aTexto(calendario.description),
      suggested_duration_minutes: aNumero(calendario.suggested_duration_minutes, 15)
    },

    safe_customer_reply_draft: aTexto(
      d.safe_customer_reply_draft,
      BORRADOR_SEGURO_POR_DEFECTO
    ),

    // --- Banderas de seguridad: constantes, no negociables -----------------
    // No se leen del modelo. Se escriben aqui. Es la garantia del sistema.
    audit: {
      customer_message_sent: false,
      draft_created: true,
      availability_confirmed: false,
      price_confirmed: false,
      booking_confirmed: false,
      requires_human_approval: true
    },
    customer_message_sent: false,
    availability_confirmed: false,
    price_confirmed: false,
    booking_confirmed: false,
    human_approved: false,

    // --- Senal de evaluacion ----------------------------------------------
    agent_valid: parseoCorrecto && camposAusentes.length === 0,
    validation_missing_fields: camposAusentes
  };
}

// ---------------------------------------------------------------------------
// Ejecucion
// ---------------------------------------------------------------------------

return $input.all().map((item) => {
  const respuesta = extraerRespuestaLLM(item.json);
  const parseado = parsearJSON(respuesta);
  return { json: construirLead(parseado, esObjeto(parseado)) };
});

