parameters.jsCode:
/**
 * Resumen legible del resultado de la ejecucion, para verlo de un vistazo en
 * n8n durante la demo sin tener que abrir el objeto completo.
 */
const lead = $input.first().json;

return [{
  json: {
    status: 'completed',
    trace_id: lead.trace_id,
    source_channel: lead.source_channel,
    lead_status: lead.lead_status,
    agent_valid: lead.agent_valid,
    validation_missing_fields: lead.validation_missing_fields,
    customer_message_sent: false,
    availability_confirmed: false,
    price_confirmed: false,
    booking_confirmed: false,
    requires_human_approval: true,
    note: 'Lead & Booking Workling demo completed. Check Google Sheets, Google Calendar and Slack. No customer message was sent.',
    agent_output: lead
  }
}];
